//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF08081.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.vSPOT_ISU_TRD_MKT_TP_CD = "1";
scwin.TR_JOB;
scwin.rowPos;
scwin.VListBzTpCd = LIST_BZ_TP_CD_712; //ETN 신고사항
scwin.fr_MktId = $c.lce.fn_getMktId();
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID());
scwin.vINFO_CONTN_TP_CD = "A";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // ETN 기타안내

scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_initItem();
        scwin.fn_list_sync();
        scwin.fn_setTitle();
    }
};
scwin.fn_setTitle = function() {
    //코스콤 전송시 주권, ETF법인은 제목앞에 회사명을 붙이므로 주석처리.
    txb_ADD_INFO_TITLE.setValue($c.stf.getObjectValue(txb_ISU_NM));
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
};
scwin.fn_list_sync = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist" + "&DIV_IDX=" + DIV_IDX_ETN_ADV_LIST_INFO + "&ISU_CD=" + txb_ISU_CD.getValue() + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};

/*
function fn_list_sync() {
	var url = "/listingCommon.do";
	url += "?SCREN_ID=" +vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01;
	url += "&method=listGeneral&outputMessageId=ADVLIST_MST_INFO_INOUT" ;
	url +=  "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" ;
	url += "&queryId=lds.stf.lstproc.etc.advlist.list.info.select" ;
	url += "&{P}param01=" + vIsurCd;
	dts_List.DataID = encodeURI(url);
	dts_List.Reset();
}
*/
scwin.fn_OpenDetail = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    dts_Item.setCellData(1, "BZ_PROCS_NO", dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO"));
    dts_Item.setCellData(1, "MKTACT_NOTI_DD", dts_List.getCellData(dts_List.getRowPosition(), "MKTACT_NOTI_DD"));
    dts_Item.setCellData(1, "INFO_TITLE", dts_List.getCellData(dts_List.getRowPosition(), "INFO_TITLE"));
    dts_Item.setCellData(1, "INFO_CONTN", dts_List.getCellData(dts_List.getRowPosition(), "INFO_CONTN"));
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate >= dts_Item.getCellData(1, "MKTACT_NOTI_DD")) {
        buttonSet.setUpdateStatus();
    } else {
        buttonSet.setErrorStatus();
    }
};
scwin.fn_SetHeader = function() {
    dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_ADVLIST_MST_INFO_INOUT";
    dts_Item.reset();
    dts_Item.insertRow();
    //alert(dts_Isu.text+" dts_Isu.text");

    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CODE_ETN_OUT";
    dts_Isu.reset();
    dts_Isu.insertRow();
};
scwin.fn_initItem = function() {
    dts_Item.Reset();
    dts_Item.insertRow();
    dts_Isu.reset();
    dts_Isu.insertRow();
    scwin.vBzProcsNo = ""; //초기화 

};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_ADD_INFO_TITLE, "제목")) return false;
    if (!$c.stf.checkMaxLength(txb_ADD_INFO_TITLE, 256, "제목")) return false;
    if (!$c.stf.checkEmptyValue(txa_INFO_CONTN, "내용")) return false;
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.rowPos = dts_List.getRowPosition();
        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};
scwin.fn_trs = function(trsIdx) {
    if (trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    dts_Item.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Item.setCellData(1, "WRT_DD", vCurDate);
    dts_Item.setCellData(1, "INFO_CONTN_TP_CD", scwin.vINFO_CONTN_TP_CD);
    trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnMktAct.do?method=saveDelist");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Item , I:dtsParm2= dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + scwin.vIsurCd + ",COUNT=2" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_ETN_ADV_LIST_INFO + ",DIV_IDX[1]=" + DIV_IDX_ETN_DELLIST_DTL_INFO;
    trs_Save.Post();
};
scwin.fn_dscl = async function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]를 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("[대상]을 선택하세요.");
        return;
    }
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    */
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    dts_Isu.setCellData(dts_Isu.getRowPosition(), "ISU_CD", txb_ISU_CD.getValue());
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68372"; //68926(기타안내사항)
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
        arr[4] = txa_INFO_CONTN.text;
        arr[5] = $c.stf.getObjectValue(txb_ADD_INFO_TITLE);
        //arr[5] = getObjectValue(txb_INFO_TITLE);

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        //CopyDataSet( dts_Isu , param_dts_mst) ;
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};



/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print = function() {
    var sDepNm_1 = "";
    var sDepNm_2 = "";
    var gDepCd = js_dep_cd.substring(0, 2);
    var pdf_rptname = "RLDSTF00004";
    if (gDepCd == '2B') {
        //유가증권 상품상장팀				
        sDepNm_1 = '확인';
        sDepNm_2 = '팀장';
    } else if (gDepCd == '26') {
        sDepNm_1 = '팀장';
        sDepNm_2 = '공시총괄팀';
        if (js_dep_cd == '2615') {
            //  기업심사팀(2615) by nhkw 
            sDepNm_1 = '팀장';
            sDepNm_2 = '상장부장';
        }
    } else if (gDepCd == '25') {
        sDepNm_1 = '팀장';
        sDepNm_2 = '상장부장';
    } else {
        sDepNm_1 = '팀장';
        sDepNm_2 = '공시총괄팀';
    }
    var tInfoContn = $c.stf.getObjectValue(txa_INFO_CONTN);
    if (tInfoContn != '') {
        tInfoContn = $c.ut.replaceAll(tInfoContn, '\n', '<br>');
        tInfoContn = $c.ut.replaceAll(tInfoContn, ' ', '&nbsp;');
    } else {
        tInfoContn = $c.ut.defaultStrHtmlSpace(tInfoContn);
    }
    var userParam = [{
        uid: "DEP_NM_1",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_1)
    }, {
        uid: "DEP_NM_2",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_2)
    }, {
        uid: "ISUR_CD",
        unm: $c.ut.defaultStrHtmlSpace(scwin.vIsurCd)
    }, {
        uid: "COM_NM",
        unm: $c.stf.getObjectValue(txb_ISU_NM)
    }, {
        uid: "TITLE",
        unm: $c.stf.getObjectValue(txb_INFO_TITLE) + " (" + $c.stf.getObjectValue(txb_ADD_INFO_TITLE) + ")"
    }, {
        uid: "BODY",
        unm: tInfoContn
    }];
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};



/********************************************** 
 * ASIS rexpert-bak 2018-04-03
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print_old = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    //dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");
    dts_Print.setCellData(1, "BODY", $c.stf.getObjectValue(txa_INFO_CONTN));

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDSTF00004";
    var userParam = [{
        uid: "ISUR_CD",
        unm: scwin.vIsurCd
    }, {
        uid: "COM_NM",
        unm: $c.stf.getObjectValue(txb_ISU_NM)
    }, {
        uid: "TITLE",
        unm: $c.stf.getObjectValue(txb_INFO_TITLE) + " (" + $c.stf.getObjectValue(txb_ADD_INFO_TITLE) + ")"
    }];
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]를 선택하세요.");
        txb_ISU_CD.focus();
        return;
    } else {
        scwin.fn_initItem();
        scwin.fn_setTitle();
        scwin.fn_list_sync();
    }
};
scwin.img_ISU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    //fn_PopFindIsu(fr_SecuGrpId);
    $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
};
scwin.btn_New_onclick = function() {
    buttonSet.setInsertStatus();
    scwin.fn_initItem();
    scwin.fn_setTitle();
};
scwin.btn_Print_onclick = function() {
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("목록에서 [대상]를 선택하세요.");
    } else {
        scwin.fn_print();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(edt_TotalCnt, "총 건수 : " + dts_List.getTotalRow());
    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    }
    dts_List.setRowPosition(dts_List.getTotalRow(), 0);
};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lce.fn_alertMsg('S');
    scwin.fn_list_sync();
    //fn_initForm("U");
    scwin.fn_initItem();
    if (scwin.TR_JOB == 'U') {
        dts_List.setRowPosition(scwin.rowPos, 0);
        scwin.fn_OpenDetail(scwin.rowPos);
    } else if (scwin.TR_JOB == 'I') {
        dts_List.setRowPosition(dts_List.getTotalRow(), 0);
        scwin.fn_OpenDetail(dts_List.getTotalRow());
    } else if (scwin.TR_JOB == 'D') {
        buttonSet.setInsertStatus();
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.cm.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    scwin.fn_SetHeader();
    buttonSet.setInsertStatus();
};
